#!/bin/sh
# Print timffle/MODIFIED-FILES.md: every upstream file Timffle has added, changed or deleted.
#
# Usage: timffle/scripts/list-modified-files.sh > timffle/MODIFIED-FILES.md
#   Compares the committed HEAD (not the working tree) with the upstream bases in timffle/UPSTREAM.env.
#   Run it after committing, then commit the regenerated file.
#
# This is Timffle's "prominent notice" that modified files were changed (Apache-2.0 section 4(b));
# the content of every change is in the git history.
set -eu

ROOT=$(cd "$(dirname "$0")/.." && pwd)
REPO=$(cd "$ROOT/.." && pwd)
# shellcheck source=../UPSTREAM.env
. "$ROOT/UPSTREAM.env"
cd "$REPO"

git cat-file -e "$RUFFLE_BASE^{commit}" 2>/dev/null || { echo "list-modified-files: $RUFFLE_BASE is not in this clone" >&2; exit 1; }
git cat-file -e "$FLASH_LSO_BASE^{commit}" 2>/dev/null || { echo "list-modified-files: $FLASH_LSO_BASE is not in this clone" >&2; exit 1; }

status() {
  awk -F '\t' '{
    s = substr($1, 1, 1)
    if (s == "M") print "| changed | `" $2 "` |"
    else if (s == "A") print "| added by Timffle | `" $2 "` |"
    else if (s == "D") print "| deleted | `" $2 "` |"
    else print "| " $1 " | `" $2 "` |"
  }'
}

cat <<HEADER
# Files modified by Timffle

Generated by \`timffle/scripts/list-modified-files.sh\` from commit \`$(git rev-parse --short=12 HEAD)\`. Do not edit by hand.

Timffle is a fork of Ruffle. The upstream files below were changed, added or deleted by Timffle (a moved file shows as deleted + added)
(Apache License 2.0, section 4(b)). Everything under \`timffle/\` is Timffle's own and is not listed.
To see a change: \`git log -p ${RUFFLE_BASE%"${RUFFLE_BASE#????????????}"}..HEAD -- <path>\`.

## Ruffle (base \`${RUFFLE_BASE%"${RUFFLE_BASE#????????????}"}\`, $RUFFLE_URL)

| Change | File |
|---|---|
HEADER
git diff --no-renames --name-status "$RUFFLE_BASE" HEAD -- . ':(exclude)timffle' ':(exclude)vendor/rust-flash-lso' \
  | LC_ALL=C sort -k2 | status

cat <<HEADER

## rust-flash-lso in \`vendor/rust-flash-lso/\` (base \`${FLASH_LSO_BASE%"${FLASH_LSO_BASE#????????????}"}\`, $FLASH_LSO_URL)

| Change | File |
|---|---|
HEADER
git diff --no-renames --name-status "$FLASH_LSO_BASE^{tree}" "HEAD:vendor/rust-flash-lso" \
  | awk -F '\t' 'BEGIN { OFS = "\t" } { $2 = "vendor/rust-flash-lso/" $2; print }' | LC_ALL=C sort -k2 | status
